import { useState } from "react";

const Btn = () => {
    const [rangi, setRangi] = useState('');

    return (
        <>
        <h1>{rangi}</h1><br/>
        <button onClick={() => setRangi('red')}>Red</button>
        <button onClick={() => setRangi('orange')}>orange</button>
        <button onClick={() => setRangi('blue')}>blue</button>
        <button onClick={() => setRangi('purple')}>purple</button>
        <button onClick={() => setRangi('yellow')}>yellow</button>
        <button onClick={() => setRangi('yellow')}>erase</button>
        </>
    )
}

export default Btn;
